	protected List<InferenceEndpoint> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of InferenceEndpoints:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all InferenceEndpoint : " );        
		List<InferenceEndpoint> collection  = new ArrayList<>();

		try {
			// call the static get method on the InferenceEndpointService
			collection = InferenceEndpointService.getInferenceEndpointInstance().getAllInferenceEndpoint();
			assertNotNull( collection, "An Empty collection of InferenceEndpoint was incorrectly returned.");
			
			// Now print out the values
			InferenceEndpoint entity = null;            
			Iterator<InferenceEndpoint> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getInferenceEndpointId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

